def order_by_points(nums):
    def digits_sum(n):
        return sum(int(i) for i in str(abs(n)))

    # Sort by (sum_of_digits, original_index) to satisfy the tie-breaker
    indexed_nums = list(enumerate(nums))
    sorted_indexed_nums = sorted(indexed_nums, key=lambda item: (digits_sum(item[1]), item[0]))
    return [value for index, value in sorted_indexed_nums]

